package lsm

import (
	"fmt"
	"os"
	"testing"
	"time"
)

func TestCompactorAddSSTable(t *testing.T) {
	config := DefaultCompactorConfig()
	config.CompactionPath = t.TempDir()
	c := NewCompactor(config)
	defer c.Stop()

	// Create test SSTable
	entries := []*Entry{
		{Key: []byte("key1"), Value: []byte("value1")},
		{Key: []byte("key2"), Value: []byte("value2")},
	}
	tmpfile, _ := os.CreateTemp(config.CompactionPath, "sstable_")
	tmpfile.Close()

	st, _ := NewSSTable(&SSTableConfig{
		BlockSize: 1024,
		Filename:  tmpfile.Name(),
	}, entries)

	c.AddSSTable(st)

	if c.SSTableCount() != 1 {
		t.Errorf("Expected 1 SSTable, got %d", c.SSTableCount())
	}

	st.Close()
}

func TestCompactorTotalSize(t *testing.T) {
	config := DefaultCompactorConfig()
	config.CompactionPath = t.TempDir()
	c := NewCompactor(config)
	defer c.Stop()

	tmpfile, _ := os.CreateTemp(config.CompactionPath, "sstable_")
	tmpfile.Close()

	entries := []*Entry{
		{Key: []byte("key1"), Value: []byte("value1")},
	}

	st, _ := NewSSTable(&SSTableConfig{
		BlockSize: 1024,
		Filename:  tmpfile.Name(),
	}, entries)

	c.AddSSTable(st)

	size := c.TotalSize()
	if size == 0 {
		t.Error("Expected non-zero total size")
	}

	st.Close()
}

func TestCompactorShouldCompact(t *testing.T) {
	config := DefaultCompactorConfig()
	config.MaxSSTables = 2
	config.CompactionPath = t.TempDir()
	c := NewCompactor(config)
	defer c.Stop()

	// Add one SSTable (shouldn't trigger compaction)
	tmpfile1, _ := os.CreateTemp(config.CompactionPath, "sstable_")
	tmpfile1.Close()
	st1, _ := NewSSTable(&SSTableConfig{
		BlockSize: 1024,
		Filename:  tmpfile1.Name(),
	}, []*Entry{{Key: []byte("a"), Value: []byte("1")}})
	c.AddSSTable(st1)

	c.mu.RLock()
	if c.shouldCompact() {
		t.Error("Should not compact with 1 SSTable")
	}
	c.mu.RUnlock()

	// Add second SSTable (should trigger)
	tmpfile2, _ := os.CreateTemp(config.CompactionPath, "sstable_")
	tmpfile2.Close()
	st2, _ := NewSSTable(&SSTableConfig{
		BlockSize: 1024,
		Filename:  tmpfile2.Name(),
	}, []*Entry{{Key: []byte("b"), Value: []byte("2")}})
	c.AddSSTable(st2)

	c.mu.RLock()
	shouldCompact := c.shouldCompact()
	c.mu.RUnlock()

	if !shouldCompact {
		t.Error("Should compact with 2 SSTables at MaxSSTables=2")
	}

	st1.Close()
	st2.Close()
}

func TestCompactorCompact(t *testing.T) {
	config := DefaultCompactorConfig()
	config.CompactionPath = t.TempDir()
	c := NewCompactor(config)
	defer c.Stop()

	// Create two SSTables with overlapping keys
	tmpfile1, _ := os.CreateTemp(config.CompactionPath, "sstable_")
	tmpfile1.Close()
	entries1 := []*Entry{
		{Key: []byte("key1"), Value: []byte("old_value1")},
		{Key: []byte("key3"), Value: []byte("value3")},
	}
	st1, _ := NewSSTable(&SSTableConfig{
		BlockSize: 1024,
		Filename:  tmpfile1.Name(),
	}, entries1)

	tmpfile2, _ := os.CreateTemp(config.CompactionPath, "sstable_")
	tmpfile2.Close()
	entries2 := []*Entry{
		{Key: []byte("key1"), Value: []byte("new_value1")},
		{Key: []byte("key2"), Value: []byte("value2")},
	}
	st2, _ := NewSSTable(&SSTableConfig{
		BlockSize: 1024,
		Filename:  tmpfile2.Name(),
	}, entries2)

	c.AddSSTable(st1)
	c.AddSSTable(st2)

	// Perform compaction
	c.mu.Lock()
	err := c.compact()
	c.mu.Unlock()

	if err != nil {
		t.Fatalf("Compaction failed: %v", err)
	}

	// Should have 1 SSTable after compaction
	if c.SSTableCount() != 1 {
		t.Errorf("Expected 1 SSTable after compaction, got %d", c.SSTableCount())
	}

	// Verify deduplication: key1 should have new_value1
	sts := c.GetSSTables()
	if len(sts) > 0 {
		val, ok := sts[0].Get([]byte("key1"))
		if !ok || string(val) != "new_value1" {
			t.Errorf("Expected 'new_value1', got %v", string(val))
		}
	}

	for _, st := range sts {
		st.Close()
	}
}

func TestCompactorDeduplication(t *testing.T) {
	entries := []*Entry{
		{Key: []byte("a"), Value: []byte("1")},
		{Key: []byte("b"), Value: []byte("2")},
		{Key: []byte("a"), Value: []byte("3")}, // Duplicate a
		{Key: []byte("c"), Value: []byte("4")},
		{Key: []byte("b"), Value: []byte("5")}, // Duplicate b
	}

	deduped := deduplicateEntries(entries)

	if len(deduped) != 3 {
		t.Errorf("Expected 3 deduped entries, got %d", len(deduped))
	}

	// Verify values are from last occurrence
	for _, e := range deduped {
		if string(e.Key) == "a" && string(e.Value) != "3" {
			t.Errorf("Expected 'a'='3', got '%s'", string(e.Value))
		}
		if string(e.Key) == "b" && string(e.Value) != "5" {
			t.Errorf("Expected 'b'='5', got '%s'", string(e.Value))
		}
	}

	// Verify sorted order
	for i := 1; i < len(deduped); i++ {
		if bytesCompare(deduped[i-1].Key, deduped[i].Key) >= 0 {
			t.Error("Deduped entries not sorted")
		}
	}
}

func TestCompactorIsRunning(t *testing.T) {
	config := DefaultCompactorConfig()
	config.CompactionPath = t.TempDir()
	c := NewCompactor(config)

	if c.IsRunning() {
		t.Error("Compactor should not be running initially")
	}

	c.Start()
	if !c.IsRunning() {
		t.Error("Compactor should be running after Start()")
	}

	c.Stop()
	if c.IsRunning() {
		t.Error("Compactor should not be running after Stop()")
	}
}

func TestCompactorBackgroundExecution(t *testing.T) {
	config := DefaultCompactorConfig()
	config.CompactInterval = 100 * time.Millisecond
	config.MaxSSTables = 2
	config.CompactionPath = t.TempDir()
	c := NewCompactor(config)

	c.Start()
	defer c.Stop()

	// Add SSTables to trigger compaction
	tmpfile1, _ := os.CreateTemp(config.CompactionPath, "sstable_")
	tmpfile1.Close()
	st1, _ := NewSSTable(&SSTableConfig{
		BlockSize: 1024,
		Filename:  tmpfile1.Name(),
	}, []*Entry{{Key: []byte("a"), Value: []byte("1")}})

	tmpfile2, _ := os.CreateTemp(config.CompactionPath, "sstable_")
	tmpfile2.Close()
	st2, _ := NewSSTable(&SSTableConfig{
		BlockSize: 1024,
		Filename:  tmpfile2.Name(),
	}, []*Entry{{Key: []byte("b"), Value: []byte("2")}})

	c.AddSSTable(st1)
	c.AddSSTable(st2)

	// Wait for background compaction to trigger
	time.Sleep(300 * time.Millisecond)

	// Should have triggered compaction (count reduced to 1)
	if c.SSTableCount() >= 2 {
		t.Logf("Compaction may not have triggered, count=%d", c.SSTableCount())
	}

	// Cleanup
	sts := c.GetSSTables()
	for _, st := range sts {
		st.Close()
	}
}

func TestCompactorLastCompactTime(t *testing.T) {
	config := DefaultCompactorConfig()
	config.CompactionPath = t.TempDir()
	c := NewCompactor(config)
	defer c.Stop()

	t0 := c.LastCompactTime()

	// Perform manual compaction
	c.mu.Lock()
	c.lastCompact = time.Now()
	c.mu.Unlock()

	t1 := c.LastCompactTime()

	if t1.Before(t0) {
		t.Error("LastCompactTime should be updated")
	}
}

func TestCompactorStats(t *testing.T) {
	config := DefaultCompactorConfig()
	config.CompactionPath = t.TempDir()
	c := NewCompactor(config)
	defer c.Stop()

	tmpfile, _ := os.CreateTemp(config.CompactionPath, "sstable_")
	tmpfile.Close()

	entries := []*Entry{
		{Key: []byte("a"), Value: []byte("1")},
		{Key: []byte("b"), Value: []byte("2")},
	}

	st, _ := NewSSTable(&SSTableConfig{
		BlockSize: 1024,
		Filename:  tmpfile.Name(),
	}, entries)

	c.AddSSTable(st)

	stats := c.GetStats()

	if stats.SSTableCount != 1 {
		t.Errorf("Expected 1 SSTable, got %d", stats.SSTableCount)
	}

	if stats.TotalSize == 0 {
		t.Error("Expected non-zero total size")
	}

	if stats.IsRunning {
		t.Error("Compactor should not be running")
	}

	st.Close()
}

func TestCompactorMultipleSSTables(t *testing.T) {
	config := DefaultCompactorConfig()
	config.CompactionPath = t.TempDir()
	c := NewCompactor(config)
	defer c.Stop()

	// Create 5 SSTables
	for i := 0; i < 5; i++ {
		tmpfile, _ := os.CreateTemp(config.CompactionPath, fmt.Sprintf("sstable_%d_", i))
		tmpfile.Close()

		entries := []*Entry{
			{Key: []byte(fmt.Sprintf("key_%d", i*2)), Value: []byte(fmt.Sprintf("value_%d", i*2))},
			{Key: []byte(fmt.Sprintf("key_%d", i*2+1)), Value: []byte(fmt.Sprintf("value_%d", i*2+1))},
		}

		st, _ := NewSSTable(&SSTableConfig{
			BlockSize: 1024,
			Filename:  tmpfile.Name(),
		}, entries)

		c.AddSSTable(st)
	}

	if c.SSTableCount() != 5 {
		t.Errorf("Expected 5 SSTables, got %d", c.SSTableCount())
	}

	// Perform compaction
	c.mu.Lock()
	err := c.compact()
	c.mu.Unlock()

	if err != nil {
		t.Fatalf("Compaction failed: %v", err)
	}

	if c.SSTableCount() != 1 {
		t.Errorf("Expected 1 SSTable after compaction, got %d", c.SSTableCount())
	}

	sts := c.GetSSTables()
	for _, st := range sts {
		st.Close()
	}
}

func TestCompactorEmptySSTables(t *testing.T) {
	config := DefaultCompactorConfig()
	config.CompactionPath = t.TempDir()
	c := NewCompactor(config)
	defer c.Stop()

	// Try to compact with no SSTables
	c.mu.Lock()
	err := c.compact()
	c.mu.Unlock()

	if err != nil {
		t.Errorf("Compacting empty list should not error: %v", err)
	}

	if c.SSTableCount() != 0 {
		t.Error("Should have 0 SSTables after empty compaction")
	}
}

func TestCompactorConfigDefaults(t *testing.T) {
	config := DefaultCompactorConfig()

	if config.CompactInterval != 10*time.Second {
		t.Errorf("Expected CompactInterval=10s, got %v", config.CompactInterval)
	}

	if config.MaxSSTables != 4 {
		t.Errorf("Expected MaxSSTables=4, got %d", config.MaxSSTables)
	}

	if config.MaxLevelSize != 10*1024*1024 {
		t.Errorf("Expected MaxLevelSize=10MB, got %d", config.MaxLevelSize)
	}
}

func TestCompactorGetSSTables(t *testing.T) {
	config := DefaultCompactorConfig()
	config.CompactionPath = t.TempDir()
	c := NewCompactor(config)
	defer c.Stop()

	tmpfile1, _ := os.CreateTemp(config.CompactionPath, "sstable_")
	tmpfile1.Close()
	st1, _ := NewSSTable(&SSTableConfig{
		BlockSize: 1024,
		Filename:  tmpfile1.Name(),
	}, []*Entry{{Key: []byte("a"), Value: []byte("1")}})

	tmpfile2, _ := os.CreateTemp(config.CompactionPath, "sstable_")
	tmpfile2.Close()
	st2, _ := NewSSTable(&SSTableConfig{
		BlockSize: 1024,
		Filename:  tmpfile2.Name(),
	}, []*Entry{{Key: []byte("b"), Value: []byte("2")}})

	c.AddSSTable(st1)
	c.AddSSTable(st2)

	sts := c.GetSSTables()

	if len(sts) != 2 {
		t.Errorf("Expected 2 SSTables, got %d", len(sts))
	}

	// Verify returned list is a copy
	sts[0] = nil
	if c.GetSSTables()[0] == nil {
		t.Error("GetSSTables should return a copy")
	}

	st1.Close()
	st2.Close()
}

