	TokenLte       TokenType = "<="
	TokenGt        TokenType = ">"
	TokenGte       TokenType = ">="
	TokenAnd       TokenType = "&&"
	TokenOr        TokenType = "||"
	TokenNot       TokenType = "!"
	TokenDollar    TokenType = "$"
	TokenLbracket  TokenType = "["
	TokenRbracket  TokenType = "]"
	TokenQuestion  TokenType = "?"

	// Delimiters
	TokenLbrace   TokenType = "{"
	TokenRbrace   TokenType = "}"
	TokenLparen   TokenType = "("
	TokenRparen   TokenType = ")"

	// Special
	TokenEOF   TokenType = "EOF"
	TokenError TokenType = "ERROR"
)

// Token represents a lexical token
type Token struct {
	Type  TokenType
	Value string
	Line  int
	Col   int
}

// Lexer tokenizes HCL-like infrastructure code
type Lexer struct {
	input  string
	pos    int
	line   int
	col    int
	start  int
	startL int
	startC int
}

// NewLexer creates a new lexer
func NewLexer(input string) *Lexer {
	return &Lexer{
		input:  input,
		pos:    0,
		line:   1,
		col:    1,
		start:  0,
		startL: 1,
		startC: 1,
	}
}

// current returns the current character
func (l *Lexer) current() byte {
	if l.pos >= len(l.input) {
		return 0
	}
	return l.input[l.pos]
}

// peek returns the next character without advancing
func (l *Lexer) peek() byte {
	if l.pos+1 >= len(l.input) {
		return 0
	}
	return l.input[l.pos+1]
}

// advance moves to the next character
func (l *Lexer) advance() {
	if l.pos < len(l.input) && l.input[l.pos] == '\n' {
		l.line++
		l.col = 1
	} else {
		l.col++
	}
	l.pos++
}

// skipWhitespace skips whitespace and comments
func (l *Lexer) skipWhitespace() {
	for l.pos < len(l.input) {
		ch := l.current()
		if ch == ' ' || ch == '\t' || ch == '\n' || ch == '\r' {
			l.advance()
		} else if ch == '#' {
			// Skip line comment
			for l.pos < len(l.input) && l.current() != '\n' {
				l.advance()
			}
		} else if ch == '/' && l.peek() == '/' {
			// Skip line comment //
			l.advance()
			l.advance()
			for l.pos < len(l.input) && l.current() != '\n' {
				l.advance()
			}
		} else if ch == '/' && l.peek() == '*' {
			// Skip block comment
			l.advance()
			l.advance()
			for l.pos < len(l.input) {
				if l.current() == '*' && l.peek() == '/' {
					l.advance()
					l.advance()
					break
				}
				l.advance()
			}
		} else {
			break
		}
	}
}

// readString reads a string literal
func (l *Lexer) readString(quote byte) string {
	l.advance() // skip opening quote

	start := l.pos
	for l.pos < len(l.input) {
		ch := l.current()
		if ch == quote {
			value := l.input[start : l.pos]
			l.advance() // skip closing quote
			return value
		}
		if ch == '\\' {
			l.advance()
			if l.pos < len(l.input) {
				l.advance()
			}
		} else {
			l.advance()
		}
	}

	return l.input[start:]
}

// readNumber reads a number literal
func (l *Lexer) readNumber() string {
	start := l.pos
	hasDecimal := false

	for l.pos < len(l.input) {
		ch := l.current()
		if ch >= '0' && ch <= '9' {
			l.advance()
		} else if ch == '.' && !hasDecimal {
			hasDecimal = true
			l.advance()
		} else if ch == 'e' || ch == 'E' {
			l.advance()
			if l.current() == '+' || l.current() == '-' {
				l.advance()
			}
		} else {
			break
		}
	}

	return l.input[start:l.pos]
}

// readIdent reads an identifier or keyword
func (l *Lexer) readIdent() string {
	start := l.pos
	for l.pos < len(l.input) {
		ch := l.current()
		if unicode.IsLetter(rune(ch)) || unicode.IsDigit(rune(ch)) || ch == '_' || ch == '-' {
			l.advance()
		} else {
			break
		}
	}
	return l.input[start:l.pos]
}

// keywordOrIdent returns the token type for a keyword or identifier
func keywordOrIdent(value string) TokenType {
	keywords := map[string]TokenType{
		"resource": TokenResource,
		"data":     TokenData,
		"variable": TokenVariable,
		"output":   TokenOutput,
		"local":    TokenLocal,
		"module":   TokenModule,
		"true":     TokenTrue,
		"false":    TokenFalse,
		"null":     TokenNull,
	}

	if typ, ok := keywords[value]; ok {
		return typ
	}
	return TokenIdent
}

// NextToken returns the next token
func (l *Lexer) NextToken() Token {
	l.skipWhitespace()

	l.start = l.pos
	l.startL = l.line
	l.startC = l.col

	if l.pos >= len(l.input) {
		return Token{Type: TokenEOF, Value: "", Line: l.line, Col: l.col}
	}

	ch := l.current()

