	singleOp := map[byte]TokenType{
		'{': TokenLbrace,
		'}': TokenRbrace,
		'(': TokenLparen,
		')': TokenRparen,
		'[': TokenLbracket,
		']': TokenRbracket,
		':': TokenColon,
		',': TokenComma,
		'.': TokenDot,
		'%': TokenPercent,
		'?': TokenQuestion,
		'$': TokenDollar,
	}

	if typ, ok := singleOp[ch]; ok {
		l.advance()
		return Token{Type: typ, Value: string(ch), Line: l.startL, Col: l.startC}
	}

