	if unicode.IsLetter(rune(ch)) || ch == '_' {
		value := l.readIdent()
		typ := keywordOrIdent(value)
		return Token{Type: typ, Value: value, Line: l.startL, Col: l.startC}
	}

	// Multi-character operators
	if ch == '=' {
		l.advance()
		if l.current() == '=' {
			l.advance()
			return Token{Type: TokenEq, Value: "==", Line: l.startL, Col: l.startC}
		}
		return Token{Type: TokenAssign, Value: "=", Line: l.startL, Col: l.startC}
	}

	if ch == '!' {
		l.advance()
		if l.current() == '=' {
			l.advance()
			return Token{Type: TokenNeq, Value: "!=", Line: l.startL, Col: l.startC}
		}
		return Token{Type: TokenNot, Value: "!", Line: l.startL, Col: l.startC}
	}

	if ch == '<' {
		l.advance()
		if l.current() == '=' {
			l.advance()
			return Token{Type: TokenLte, Value: "<=", Line: l.startL, Col: l.startC}
		}
		return Token{Type: TokenLt, Value: "<", Line: l.startL, Col: l.startC}
	}

	if ch == '>' {
		l.advance()
		if l.current() == '=' {
			l.advance()
			return Token{Type: TokenGte, Value: ">=", Line: l.startL, Col: l.startC}
		}
		return Token{Type: TokenGt, Value: ">", Line: l.startL, Col: l.startC}
	}

	if ch == '&' {
		l.advance()
		if l.current() == '&' {
			l.advance()
			return Token{Type: TokenAnd, Value: "&&", Line: l.startL, Col: l.startC}
		}
		return Token{Type: TokenError, Value: fmt.Sprintf("unexpected character: %c", ch), Line: l.startL, Col: l.startC}
	}

	if ch == '|' {
		l.advance()
		if l.current() == '|' {
			l.advance()
			return Token{Type: TokenOr, Value: "||", Line: l.startL, Col: l.startC}
		}
		return Token{Type: TokenError, Value: fmt.Sprintf("unexpected character: %c", ch), Line: l.startL, Col: l.startC}
	}

	if ch == '+' {
		l.advance()
		return Token{Type: TokenPlus, Value: "+", Line: l.startL, Col: l.startC}
	}

	if ch == '-' {
		l.advance()
		return Token{Type: TokenMinus, Value: "-", Line: l.startL, Col: l.startC}
	}

	if ch == '*' {
		l.advance()
		return Token{Type: TokenStar, Value: "*", Line: l.startL, Col: l.startC}
	}

	if ch == '/' {
		l.advance()
		return Token{Type: TokenSlash, Value: "/", Line: l.startL, Col: l.startC}
	}

	// Unknown character
	l.advance()
	return Token{Type: TokenError, Value: fmt.Sprintf("unexpected character: %c", ch), Line: l.startL, Col: l.startC}
}

// TokenizeAll returns all tokens from the input
func (l *Lexer) TokenizeAll() []Token {
	var tokens []Token
	for {
		tok := l.NextToken()
		tokens = append(tokens, tok)
		if tok.Type == TokenEOF {
			break
		}
	}
	return tokens
}

