		t.Errorf("Expected error token for @, got %v", tok.Type)
	}
}

func TestLexerMultilineString(t *testing.T) {
	input := `"first line
second line"`
	lex := NewLexer(input)

	tok := lex.NextToken()
	if tok.Type != TokenString {
		t.Errorf("Expected string, got %v", tok.Type)
	}

	// String should contain newline
	if tok.Value != "first line\nsecond line" {
		t.Errorf("Expected multiline content, got %q", tok.Value)
	}
}

func TestLexerTokenizeAll(t *testing.T) {
	input := "resource {}"
	lex := NewLexer(input)

	tokens := lex.TokenizeAll()

	expected := []TokenType{TokenResource, TokenLbrace, TokenRbrace, TokenEOF}
	if len(tokens) != len(expected) {
		t.Errorf("Expected %d tokens, got %d", len(expected), len(tokens))
	}

	for i, exp := range expected {
		if tokens[i].Type != exp {
			t.Errorf("Token %d: expected %v, got %v", i, exp, tokens[i].Type)
		}
	}
}

