package parser

import (
	"fmt"
	"strconv"

	"github.com/kimjindol2025/freelang-iac/internal/iac/ast"
	"github.com/kimjindol2025/freelang-iac/internal/iac/lexer"
)

// Parser parses tokens into an AST
type Parser struct {
	tokens   []lexer.Token
	pos      int
	errors   []string
	curPrec  int
	infixMap map[lexer.TokenType]InfixParser
	prefixMap map[lexer.TokenType]PrefixParser
}

// PrefixParser parses a prefix expression
type PrefixParser func() ast.Expr

// InfixParser parses an infix expression
type InfixParser func(left ast.Expr) ast.Expr

// Precedence levels
const (
	PrecLowest    = iota
	PrecOr
	PrecAnd
	PrecEqual
	PrecRelation
	PrecAdditive
	PrecMultiplicative
	PrecUnary
	PrecPostfix
	PrecPrimary
)

var precedences = map[lexer.TokenType]int{
	lexer.TokenOr:     PrecOr,
	lexer.TokenAnd:    PrecAnd,
	lexer.TokenEq:     PrecEqual,
	lexer.TokenNeq:    PrecEqual,
	lexer.TokenLt:     PrecRelation,
	lexer.TokenLte:    PrecRelation,
	lexer.TokenGt:     PrecRelation,
	lexer.TokenGte:    PrecRelation,
	lexer.TokenPlus:   PrecAdditive,
	lexer.TokenMinus:  PrecAdditive,
	lexer.TokenStar:   PrecMultiplicative,
	lexer.TokenSlash:  PrecMultiplicative,
	lexer.TokenPercent: PrecMultiplicative,
	lexer.TokenDot:    PrecPostfix,
	lexer.TokenLbracket: PrecPostfix,
	lexer.TokenLparen: PrecPostfix,
	lexer.TokenQuestion: PrecOr - 1,
}

// NewParser creates a new parser
func NewParser(tokens []lexer.Token) *Parser {
	p := &Parser{
		tokens:     tokens,
		pos:        0,
		errors:     []string{},
		infixMap:   make(map[lexer.TokenType]InfixParser),
		prefixMap:  make(map[lexer.TokenType]PrefixParser),
	}

	// Register prefix parsers
	p.prefixMap[lexer.TokenIdent] = p.parseIdent
	p.prefixMap[lexer.TokenString] = p.parseString
	p.prefixMap[lexer.TokenNumber] = p.parseNumber
	p.prefixMap[lexer.TokenTrue] = p.parseBool
	p.prefixMap[lexer.TokenFalse] = p.parseBool
	p.prefixMap[lexer.TokenNull] = p.parseNull
	p.prefixMap[lexer.TokenLbrace] = p.parseBlock
	p.prefixMap[lexer.TokenLbracket] = p.parseList
	p.prefixMap[lexer.TokenLparen] = p.parseGrouped
	p.prefixMap[lexer.TokenNot] = p.parseUnary
	p.prefixMap[lexer.TokenMinus] = p.parseUnary
	p.prefixMap[lexer.TokenPlus] = p.parseUnary
	p.prefixMap[lexer.TokenDollar] = p.parseDollar

	// Register infix parsers
	p.infixMap[lexer.TokenPlus] = p.parseBinary
	p.infixMap[lexer.TokenMinus] = p.parseBinary
	p.infixMap[lexer.TokenStar] = p.parseBinary
	p.infixMap[lexer.TokenSlash] = p.parseBinary
	p.infixMap[lexer.TokenPercent] = p.parseBinary
	p.infixMap[lexer.TokenEq] = p.parseBinary
	p.infixMap[lexer.TokenNeq] = p.parseBinary
	p.infixMap[lexer.TokenLt] = p.parseBinary
	p.infixMap[lexer.TokenLte] = p.parseBinary
	p.infixMap[lexer.TokenGt] = p.parseBinary
	p.infixMap[lexer.TokenGte] = p.parseBinary
	p.infixMap[lexer.TokenAnd] = p.parseBinary
	p.infixMap[lexer.TokenOr] = p.parseBinary
	p.infixMap[lexer.TokenDot] = p.parseAttr
	p.infixMap[lexer.TokenLbracket] = p.parseIndex
	p.infixMap[lexer.TokenLparen] = p.parseCall
	p.infixMap[lexer.TokenQuestion] = p.parseConditional

	return p
}

// current returns the current token
func (p *Parser) current() lexer.Token {
	if p.pos >= len(p.tokens) {
		return lexer.Token{Type: lexer.TokenEOF}
	}
	return p.tokens[p.pos]
}

// peek returns the next token
func (p *Parser) peek() lexer.Token {
	if p.pos+1 >= len(p.tokens) {
		return lexer.Token{Type: lexer.TokenEOF}
	}
	return p.tokens[p.pos+1]
}

// advance moves to the next token
func (p *Parser) advance() {
	p.pos++
}

// expect advances if current token matches expected type
func (p *Parser) expect(typ lexer.TokenType) bool {
	if p.current().Type == typ {
		p.advance()
		return true
	}
	p.errors = append(p.errors, fmt.Sprintf("Expected %v, got %v", typ, p.current().Type))
	return false
}

// skipNewlines skips any newlines
func (p *Parser) skipNewlines() {
	// This would be used if we track newlines in tokens
}

// Parse parses the tokens into a program AST
func (p *Parser) Parse() *ast.Program {
	program := &ast.Program{
		Statements: []ast.Stmt{},
	}

	for p.current().Type != lexer.TokenEOF {
		stmt := p.parseStatement()
		if stmt != nil {
			program.Statements = append(program.Statements, stmt)
		}
		p.skipNewlines()
	}

	return program
}

// parseStatement parses a statement
func (p *Parser) parseStatement() ast.Stmt {
	switch p.current().Type {
	case lexer.TokenResource:
		return p.parseResource()
	case lexer.TokenData:
		return p.parseData()
	case lexer.TokenVariable:
		return p.parseVariable()
	case lexer.TokenOutput:
		return p.parseOutput()
	case lexer.TokenLocal:
		return p.parseLocal()
	case lexer.TokenModule:
		return p.parseModule()
	default:
		p.errors = append(p.errors, fmt.Sprintf("Unexpected statement: %v", p.current().Type))
		p.advance()
		return nil
	}
}

// parseResource parses a resource block
func (p *Parser) parseResource() *ast.Resource {
	p.expect(lexer.TokenResource)

	if p.current().Type != lexer.TokenString {
		p.errors = append(p.errors, "Expected resource type string")
		return nil
	}
	typ := p.current().Value
	p.advance()

	if p.current().Type != lexer.TokenString {
		p.errors = append(p.errors, "Expected resource name string")
		return nil
	}
	name := p.current().Value
	p.advance()

	block := p.parseBlock()
	if block == nil {
		return nil
	}

	return &ast.Resource{
		Type:  typ,
		Name:  name,
		Block: block,
	}
}

// parseData parses a data block
func (p *Parser) parseData() *ast.Data {
	p.expect(lexer.TokenData)

	if p.current().Type != lexer.TokenString {
		p.errors = append(p.errors, "Expected data type string")
		return nil
	}
	typ := p.current().Value
	p.advance()

	if p.current().Type != lexer.TokenString {
		p.errors = append(p.errors, "Expected data name string")
		return nil
	}
	name := p.current().Value
	p.advance()

	block := p.parseBlock()
	if block == nil {
		return nil
	}

	return &ast.Data{
		Type:  typ,
		Name:  name,
		Block: block,
	}
}

// parseVariable parses a variable block
func (p *Parser) parseVariable() *ast.Variable {
	p.expect(lexer.TokenVariable)

	if p.current().Type != lexer.TokenString {
		p.errors = append(p.errors, "Expected variable name string")
		return nil
	}
	name := p.current().Value
	p.advance()

	block := p.parseBlock()
	if block == nil {
		return nil
	}

	return &ast.Variable{
		Name:  name,
		Block: block,
	}
}

// parseOutput parses an output block
func (p *Parser) parseOutput() *ast.Output {
	p.expect(lexer.TokenOutput)

	if p.current().Type != lexer.TokenString {
		p.errors = append(p.errors, "Expected output name string")
		return nil
	}
	name := p.current().Value
	p.advance()

	block := p.parseBlock()
	if block == nil {
		return nil
	}

	return &ast.Output{
		Name:  name,
		Block: block,
	}
}

// parseLocal parses a local block
func (p *Parser) parseLocal() *ast.Local {
	p.expect(lexer.TokenLocal)

	block := p.parseBlock()
	if block == nil {
		return nil
	}

	return &ast.Local{
		Block: block,
	}
}

// parseModule parses a module block
func (p *Parser) parseModule() *ast.Module {
	p.expect(lexer.TokenModule)

	if p.current().Type != lexer.TokenString {
		p.errors = append(p.errors, "Expected module name string")
		return nil
	}
	name := p.current().Value
	p.advance()

	block := p.parseBlock()
	if block == nil {
		return nil
	}

	return &ast.Module{
		Name:  name,
		Block: block,
	}
}

// parseBlock parses a block { ... }
func (p *Parser) parseBlock() *ast.Block {
	if !p.expect(lexer.TokenLbrace) {
		return nil
	}

	pairs := []*ast.Pair{}

	for p.current().Type != lexer.TokenRbrace && p.current().Type != lexer.TokenEOF {
		if p.current().Type != lexer.TokenIdent {
			p.errors = append(p.errors, fmt.Sprintf("Expected identifier, got %v", p.current().Type))
			p.advance()
			continue
		}

		key := p.current().Value
		p.advance()

		if !p.expect(lexer.TokenAssign) {
			continue
		}

		value := p.parseExpression(PrecLowest)
		if value == nil {
			continue
		}

		pairs = append(pairs, &ast.Pair{
			Key:   key,
			Value: value,
		})

		// Skip commas
		if p.current().Type == lexer.TokenComma {
			p.advance()
		}
	}

	if !p.expect(lexer.TokenRbrace) {
		return nil
	}

	return &ast.Block{
		Pairs: pairs,
	}
}

// parseExpression parses an expression
func (p *Parser) parseExpression(prec int) ast.Expr {
	prefixFn := p.prefixMap[p.current().Type]
	if prefixFn == nil {
		p.errors = append(p.errors, fmt.Sprintf("No prefix parser for %v", p.current().Type))
		return nil
	}

	left := prefixFn()

	for prec < p.getPrecedence() {
		infixFn := p.infixMap[p.current().Type]
		if infixFn == nil {
			return left
		}

		left = infixFn(left)
	}

	return left
}

// getPrecedence returns the precedence of the current token
func (p *Parser) getPrecedence() int {
	if prec, ok := precedences[p.current().Type]; ok {
		return prec
	}
	return PrecLowest
}

// parseIdent parses an identifier
func (p *Parser) parseIdent() ast.Expr {
	ident := &ast.Ident{
		Name: p.current().Value,
	}
	p.advance()
	return ident
}

// parseString parses a string literal
func (p *Parser) parseString() ast.Expr {
	lit := &ast.Literal{
		Value: p.current().Value,
		Kind:  ast.KindString,
	}
	p.advance()
	return lit
}

// parseNumber parses a number literal
func (p *Parser) parseNumber() ast.Expr {
	value := p.current().Value
	num, err := strconv.ParseFloat(value, 64)
	if err != nil {
		p.errors = append(p.errors, fmt.Sprintf("Invalid number: %s", value))
		num = 0
	}

	lit := &ast.Literal{
		Value: num,
		Kind:  ast.KindNumber,
	}
	p.advance()
	return lit
}

// parseBool parses a boolean literal
func (p *Parser) parseBool() ast.Expr {
	value := p.current().Type == lexer.TokenTrue
	lit := &ast.Literal{
		Value: value,
		Kind:  ast.KindBool,
	}
	p.advance()
	return lit
}

// parseNull parses a null literal
func (p *Parser) parseNull() ast.Expr {
	lit := &ast.Literal{
		Value: nil,
		Kind:  ast.KindNull,
	}
	p.advance()
	return lit
}

// parseBlock parses a block (as expression)
func (p *Parser) parseBlock() ast.Expr {
	return p.parseBlockStmt().(*ast.Block)
}

// parseBlockStmt parses a block statement
func (p *Parser) parseBlockStmt() interface{} {
	if !p.expect(lexer.TokenLbrace) {
		return nil
	}

	pairs := []*ast.Pair{}

	for p.current().Type != lexer.TokenRbrace && p.current().Type != lexer.TokenEOF {
		if p.current().Type != lexer.TokenIdent {
			p.errors = append(p.errors, fmt.Sprintf("Expected identifier, got %v", p.current().Type))
			p.advance()
			continue
		}

		key := p.current().Value
		p.advance()

		if !p.expect(lexer.TokenAssign) {
			continue
		}

		value := p.parseExpression(PrecLowest)
		if value == nil {
			continue
		}

		pairs = append(pairs, &ast.Pair{
			Key:   key,
			Value: value,
		})

		if p.current().Type == lexer.TokenComma {
			p.advance()
		}
	}

	if !p.expect(lexer.TokenRbrace) {
		return nil
	}

	return &ast.Block{
		Pairs: pairs,
	}
}

// parseList parses a list [ ... ]
func (p *Parser) parseList() ast.Expr {
	if !p.expect(lexer.TokenLbracket) {
		return nil
	}

	items := []ast.Expr{}

	for p.current().Type != lexer.TokenRbracket && p.current().Type != lexer.TokenEOF {
		item := p.parseExpression(PrecLowest)
		if item == nil {
			break
		}
		items = append(items, item)

		if p.current().Type == lexer.TokenComma {
			p.advance()
		}
	}

	if !p.expect(lexer.TokenRbracket) {
		return nil
	}

	return &ast.List{
		Items: items,
	}
}

// parseGrouped parses a grouped expression
func (p *Parser) parseGrouped() ast.Expr {
	if !p.expect(lexer.TokenLparen) {
		return nil
	}

	expr := p.parseExpression(PrecLowest)

	if !p.expect(lexer.TokenRparen) {
		return nil
	}

	return expr
}

// parseUnary parses a unary expression
func (p *Parser) parseUnary() ast.Expr {
	op := p.current().Value
	p.advance()

	expr := p.parseExpression(PrecUnary)
	if expr == nil {
		return nil
	}

	return &ast.UnaryOp{
		Op:   op,
		Expr: expr,
	}
}

// parseBinary parses a binary expression
func (p *Parser) parseBinary(left ast.Expr) ast.Expr {
	op := p.current().Value
	prec := p.getPrecedence()
	p.advance()

	right := p.parseExpression(prec + 1)
	if right == nil {
		return nil
	}

	return &ast.BinaryOp{
		Left:  left,
		Op:    op,
		Right: right,
	}
}

// parseAttr parses attribute access
func (p *Parser) parseAttr(left ast.Expr) ast.Expr {
	p.advance() // skip .

	if p.current().Type != lexer.TokenIdent {
		p.errors = append(p.errors, fmt.Sprintf("Expected identifier after ., got %v", p.current().Type))
		return left
	}

	attr := p.current().Value
	p.advance()

	return &ast.Attr{
		Expr: left,
		Attr: attr,
	}
}

// parseIndex parses indexing
func (p *Parser) parseIndex(left ast.Expr) ast.Expr {
	p.advance() // skip [

	index := p.parseExpression(PrecLowest)
	if index == nil {
		return left
	}

	if !p.expect(lexer.TokenRbracket) {
		return left
	}

	return &ast.Index{
		Expr:  left,
		Index: index,
	}
}

// parseCall parses a function call
func (p *Parser) parseCall(left ast.Expr) ast.Expr {
	if ident, ok := left.(*ast.Ident); !ok {
		p.errors = append(p.errors, "Can only call identifiers")
		return left
	} else {
		p.advance() // skip (

		args := []ast.Expr{}
		for p.current().Type != lexer.TokenRparen && p.current().Type != lexer.TokenEOF {
			arg := p.parseExpression(PrecLowest)
			if arg == nil {
				break
			}
			args = append(args, arg)

			if p.current().Type == lexer.TokenComma {
				p.advance()
			}
		}

		if !p.expect(lexer.TokenRparen) {
			return left
		}

		return &ast.Call{
			Name: ident.Name,
			Args: args,
		}
	}
}

// parseConditional parses a ternary conditional
func (p *Parser) parseConditional(cond ast.Expr) ast.Expr {
	p.advance() // skip ?

	trueExpr := p.parseExpression(PrecLowest)
	if trueExpr == nil {
		return cond
	}

	if !p.expect(lexer.TokenColon) {
		return cond
	}

	falseExpr := p.parseExpression(PrecLowest)
	if falseExpr == nil {
		return cond
	}

	return &ast.Conditional{
		Cond:  cond,
		True:  trueExpr,
		False: falseExpr,
	}
}

// parseDollar parses $ prefix (for variable interpolation)
func (p *Parser) parseDollar() ast.Expr {
	p.advance() // skip $

	if p.current().Type != lexer.TokenLbrace {
		p.errors = append(p.errors, "Expected { after $")
		return nil
	}
	p.advance() // skip {

	expr := p.parseExpression(PrecLowest)
	if expr == nil {
		return nil
	}

	if !p.expect(lexer.TokenRbrace) {
		return nil
	}

	return expr
}

// Errors returns parsing errors
func (p *Parser) Errors() []string {
	return p.errors
}

