func (p *Parser) parseNull() ast.Expr {
	lit := &ast.Literal{
		Value: nil,
		Kind:  ast.KindNull,
	}
	p.advance()
	return lit
}

// parseBlockExpr parses a block (as expression)
func (p *Parser) parseBlockExpr() ast.Expr {
	return p.parseBlockStmt()
}

// parseBlockStmt parses a block as a statement
func (p *Parser) parseBlockStmt() *ast.Block {
