package interpreter

import (
	"fmt"
	"strconv"
	"strings"
)

// Value represents a runtime value
type Value interface {
	Type() string
	String() string
	Truthy() bool
}

// Null represents a null value
type Null struct{}

func (*Null) Type() string {
	return "null"
}

func (*Null) String() string {
	return "null"
}

func (*Null) Truthy() bool {
	return false
}

// Bool represents a boolean value
type Bool struct {
	Value bool
}

func (b *Bool) Type() string {
	return "bool"
}

func (b *Bool) String() string {
	if b.Value {
		return "true"
	}
	return "false"
}

func (b *Bool) Truthy() bool {
	return b.Value
}

// Number represents a numeric value
type Number struct {
	Value float64
}

func (n *Number) Type() string {
	return "number"
}

func (n *Number) String() string {
	if n.Value == float64(int64(n.Value)) {
		return fmt.Sprintf("%d", int64(n.Value))
	}
	return fmt.Sprintf("%g", n.Value)
}

func (n *Number) Truthy() bool {
	return n.Value != 0
}

// String represents a string value
type String struct {
	Value string
}

func (s *String) Type() string {
	return "string"
}

func (s *String) String() string {
	return s.Value
}

func (s *String) Truthy() bool {
	return s.Value != ""
}

// List represents a list value
type List struct {
	Items []Value
}

func (l *List) Type() string {
	return "list"
}

func (l *List) String() string {
	var items []string
	for _, item := range l.Items {
		items = append(items, item.String())
	}
	return "[" + strings.Join(items, ", ") + "]"
}

func (l *List) Truthy() bool {
	return len(l.Items) > 0
}

// Map represents a map/object value
type Map struct {
	Pairs map[string]Value
}

func (m *Map) Type() string {
	return "map"
}

func (m *Map) String() string {
	var items []string
	for k, v := range m.Pairs {
		items = append(items, fmt.Sprintf("%s = %s", k, v.String()))
	}
	return "{" + strings.Join(items, ", ") + "}"
}

func (m *Map) Truthy() bool {
	return len(m.Pairs) > 0
}

// Error represents an error value
type Error struct {
	Message string
}

func (e *Error) Type() string {
	return "error"
}

func (e *Error) String() string {
	return fmt.Sprintf("error: %s", e.Message)
}

func (e *Error) Truthy() bool {
	return false
}

// ToNumber converts a value to a number
func ToNumber(v Value) (*Number, error) {
	switch val := v.(type) {
	case *Number:
		return val, nil
	case *String:
		num, err := strconv.ParseFloat(val.Value, 64)
		if err != nil {
			return nil, fmt.Errorf("cannot convert string %q to number", val.Value)
		}
		return &Number{Value: num}, nil
	case *Bool:
		if val.Value {
			return &Number{Value: 1}, nil
		}
		return &Number{Value: 0}, nil
	case *Null:
		return nil, fmt.Errorf("cannot convert null to number")
	default:
		return nil, fmt.Errorf("cannot convert %s to number", v.Type())
	}
}

// ToString converts a value to a string
func ToString(v Value) (*String, error) {
	switch val := v.(type) {
	case *String:
		return val, nil
	case *Number:
		return &String{Value: val.String()}, nil
	case *Bool:
		return &String{Value: val.String()}, nil
	case *Null:
		return &String{Value: "null"}, nil
	case *List, *Map:
		return &String{Value: val.String()}, nil
	default:
		return nil, fmt.Errorf("cannot convert %s to string", v.Type())
	}
}

// ToBool converts a value to a boolean
func ToBool(v Value) *Bool {
	return &Bool{Value: v.Truthy()}
}

// ToList converts a value to a list
func ToList(v Value) (*List, error) {
	switch val := v.(type) {
	case *List:
		return val, nil
	case *String:
		// Convert string to list of characters
		items := make([]Value, len(val.Value))
		for i, ch := range val.Value {
			items[i] = &String{Value: string(ch)}
		}
		return &List{Items: items}, nil
	default:
		return nil, fmt.Errorf("cannot convert %s to list", v.Type())
	}
}

// ToMap converts a value to a map
func ToMap(v Value) (*Map, error) {
	switch val := v.(type) {
	case *Map:
		return val, nil
	default:
		return nil, fmt.Errorf("cannot convert %s to map", v.Type())
	}
}

// IsEqual compares two values for equality
func IsEqual(a, b Value) bool {
	if a.Type() != b.Type() {
		return false
	}

	switch av := a.(type) {
	case *Null:
		return true
	case *Bool:
		return av.Value == b.(*Bool).Value
	case *Number:
		return av.Value == b.(*Number).Value
	case *String:
		return av.Value == b.(*String).Value
	case *List:
		bv := b.(*List)
		if len(av.Items) != len(bv.Items) {
			return false
		}
		for i := range av.Items {
			if !IsEqual(av.Items[i], bv.Items[i]) {
				return false
			}
		}
		return true
	case *Map:
		bv := b.(*Map)
		if len(av.Pairs) != len(bv.Pairs) {
			return false
		}
		for k, v := range av.Pairs {
			if bv_val, ok := bv.Pairs[k]; !ok || !IsEqual(v, bv_val) {
				return false
			}
		}
		return true
	default:
		return false
	}
}

// IsLess compares two values (for < operator)
func IsLess(a, b Value) (bool, error) {
	switch av := a.(type) {
	case *Number:
		bv, ok := b.(*Number)
		if !ok {
			return false, fmt.Errorf("cannot compare number and %s", b.Type())
		}
		return av.Value < bv.Value, nil
	case *String:
		bv, ok := b.(*String)
		if !ok {
			return false, fmt.Errorf("cannot compare string and %s", b.Type())
		}
		return av.Value < bv.Value, nil
	default:
		return false, fmt.Errorf("cannot compare %s", a.Type())
	}
}

