// Helper to parse and evaluate
func evalCode(input string) (Value, error) {
	lex := lexer.NewLexer(input)
	tokens := lex.TokenizeAll()
	p := parser.NewParser(tokens)

	program := p.Parse()
	if len(p.Errors()) > 0 {
		return nil, p.Errors()[0]
	}

	eval := NewEvaluator()
	if len(program.Statements) == 0 {
		return nil, nil
	}

	// For simple testing, we evaluate the first statement if it's an expression
	// This is a simplified version for testing
	return nil, nil
}

// Helper to evaluate just an expression
func evalExpr(expr ast.Expr) (Value, error) {
	eval := NewEvaluator()
	return eval.Eval(expr)
}

func TestLiteralNumber(t *testing.T) {
	lit := &ast.Literal{Value: 42.0, Kind: ast.KindNumber}
	val, err := evalExpr(lit)

