package engine

import (
	"fmt"

	"github.com/kimjindol2025/freelang-iac/internal/iac/ast"
	"github.com/kimjindol2025/freelang-iac/internal/iac/interpreter"
	"github.com/kimjindol2025/freelang-iac/internal/iac/lexer"
	"github.com/kimjindol2025/freelang-iac/internal/iac/parser"
)

// Engine orchestrates lexing, parsing, and evaluation
type Engine struct {
	source    string
	tokens    []lexer.Token
	program   *ast.Program
	evaluator *interpreter.Evaluator
	errors    []string
}

// NewEngine creates a new engine
func NewEngine(source string) *Engine {
	return &Engine{
		source:    source,
		errors:    []string{},
		evaluator: interpreter.NewEvaluator(),
	}
}

// Lex tokenizes the source code
func (e *Engine) Lex() error {
	lex := lexer.NewLexer(e.source)
	e.tokens = lex.TokenizeAll()

	// Check for lexer errors
	for _, tok := range e.tokens {
		if tok.Type == lexer.TokenError {
			e.errors = append(e.errors, fmt.Sprintf("Lexer error at %d:%d: %s", tok.Line, tok.Col, tok.Value))
		}
	}

	if len(e.errors) > 0 {
		return fmt.Errorf("lexing failed")
	}

	return nil
}

// Parse builds the AST
func (e *Engine) Parse() error {
	if len(e.tokens) == 0 {
		return fmt.Errorf("no tokens to parse")
	}

	p := parser.NewParser(e.tokens)
	e.program = p.Parse()

	if len(p.Errors()) > 0 {
		e.errors = append(e.errors, p.Errors()...)
		return fmt.Errorf("parsing failed")
	}

	return nil
}

// Evaluate runs the program
func (e *Engine) Evaluate() error {
	if e.program == nil {
		return fmt.Errorf("no program to evaluate")
	}

	for _, stmt := range e.program.Statements {
		if err := e.evaluateStatement(stmt); err != nil {
			e.errors = append(e.errors, err.Error())
		}
	}

	if len(e.errors) > 0 {
		return fmt.Errorf("evaluation failed")
	}

	return nil
}

// evaluateStatement evaluates a single statement
func (e *Engine) evaluateStatement(stmt ast.Stmt) error {
	switch node := stmt.(type) {
	case *ast.Resource:
		return e.evaluateResource(node)
	case *ast.Data:
		return e.evaluateData(node)
	case *ast.Variable:
		return e.evaluateVariable(node)
	case *ast.Output:
		return e.evaluateOutput(node)
	case *ast.Local:
		return e.evaluateLocal(node)
	case *ast.Module:
		return e.evaluateModule(node)
	default:
		return fmt.Errorf("unknown statement type: %T", stmt)
	}
}

// evaluateResource evaluates a resource block
func (e *Engine) evaluateResource(resource *ast.Resource) error {
	if resource.Block == nil {
		return fmt.Errorf("resource %q %q has no block", resource.Type, resource.Name)
	}

	// Store resource in evaluator environment
	key := fmt.Sprintf("%s_%s", resource.Type, resource.Name)
	val, err := e.evaluator.Eval(resource.Block)
	if err != nil {
		return fmt.Errorf("failed to evaluate resource %q: %w", key, err)
	}

	e.evaluator.env.Set(key, val)
	return nil
}

// evaluateData evaluates a data block
func (e *Engine) evaluateData(data *ast.Data) error {
	if data.Block == nil {
		return fmt.Errorf("data %q %q has no block", data.Type, data.Name)
	}

	// Store data in evaluator environment
	key := fmt.Sprintf("data_%s_%s", data.Type, data.Name)
	val, err := e.evaluator.Eval(data.Block)
	if err != nil {
		return fmt.Errorf("failed to evaluate data %q: %w", key, err)
	}

	e.evaluator.env.Set(key, val)
	return nil
}

// evaluateVariable evaluates a variable block
func (e *Engine) evaluateVariable(variable *ast.Variable) error {
	if variable.Block == nil {
		return fmt.Errorf("variable %q has no block", variable.Name)
	}

	// Store variable in evaluator environment
	val, err := e.evaluator.Eval(variable.Block)
	if err != nil {
		return fmt.Errorf("failed to evaluate variable %q: %w", variable.Name, err)
	}

	e.evaluator.env.Set(fmt.Sprintf("var_%s", variable.Name), val)
	return nil
}

// evaluateOutput evaluates an output block
func (e *Engine) evaluateOutput(output *ast.Output) error {
	if output.Block == nil {
		return fmt.Errorf("output %q has no block", output.Name)
	}

	// Store output in evaluator environment
	val, err := e.evaluator.Eval(output.Block)
	if err != nil {
		return fmt.Errorf("failed to evaluate output %q: %w", output.Name, err)
	}

	e.evaluator.env.Set(fmt.Sprintf("output_%s", output.Name), val)
	return nil
}

// evaluateLocal evaluates a local block
func (e *Engine) evaluateLocal(local *ast.Local) error {
	if local.Block == nil {
		return fmt.Errorf("local block has no pairs")
	}

	// Evaluate local values
	val, err := e.evaluator.Eval(local.Block)
	if err != nil {
		return fmt.Errorf("failed to evaluate local: %w", err)
	}

	// Store locals in evaluator environment
	if m, ok := val.(*interpreter.Map); ok {
		for k, v := range m.Pairs {
			e.evaluator.env.Set(fmt.Sprintf("local_%s", k), v)
		}
	}

	return nil
}

// evaluateModule evaluates a module block
func (e *Engine) evaluateModule(module *ast.Module) error {
	if module.Block == nil {
		return fmt.Errorf("module %q has no block", module.Name)
	}

	// Store module in evaluator environment
	val, err := e.evaluator.Eval(module.Block)
	if err != nil {
		return fmt.Errorf("failed to evaluate module %q: %w", module.Name, err)
	}

	e.evaluator.env.Set(fmt.Sprintf("module_%s", module.Name), val)
	return nil
}

// Run executes all phases: lex, parse, evaluate
func (e *Engine) Run() error {
	if err := e.Lex(); err != nil {
		return err
	}

	if err := e.Parse(); err != nil {
		return err
	}

	if err := e.Evaluate(); err != nil {
		return err
	}

	return nil
}

// GetVariable retrieves a variable value
func (e *Engine) GetVariable(name string) (interpreter.Value, bool) {
	return e.evaluator.env.Get(name)
}

// GetAllVariables returns all variables in the environment
func (e *Engine) GetAllVariables() map[string]interpreter.Value {
	vars := make(map[string]interpreter.Value)

	// This is a simplified version - a full implementation would walk the environment
	// For now, we'll just return an empty map
	return vars
}

// Errors returns all accumulated errors
func (e *Engine) Errors() []string {
	return e.errors
}

// HasErrors checks if there are any errors
func (e *Engine) HasErrors() bool {
	return len(e.errors) > 0
}

