import (
	"testing"

	"github.com/kimjindol2025/freelang-iac/internal/iac/interpreter"
)

func TestEngineSimpleVariable(t *testing.T) {
	code := `variable "instance_count" {
  type = "number"
  default = 2
}`

	engine := NewEngine(code)
	if err := engine.Run(); err != nil {
		t.Fatalf("Engine failed: %v", err)
	}

	if engine.HasErrors() {
		for _, err := range engine.Errors() {
			t.Logf("Error: %s", err)
		}
		t.Fatalf("Engine had errors")
	}
}

