toolUseResult.originalFile:
package interpreter

import (
	"fmt"
	"math"
	"strings"

	"github.com/kimjindol2025/freelang-iac/internal/iac/ast"
)

// Environment holds variable bindings
type Environment struct {
	vars   map[string]Value
	parent *Environment
}

// NewEnvironment creates a new environment
func NewEnvironment() *Environment {
	return &Environment{
		vars:   make(map[string]Value),
		parent: nil,
	}
}

// NewChild creates a child environment
func (e *Environment) NewChild() *Environment {
	return &Environment{
		vars:   make(map[string]Value),
		parent: e,
	}
}

// Set sets a variable in the current environment
func (e *Environment) Set(name string, value Value) {
	e.vars[name] = value
}

// Get retrieves a variable, checking parent environments
func (e *Environment) Get(name string) (Value, bool) {
	if val, ok := e.vars[name]; ok {
		return val, true
	}
	if e.parent != nil {
		return e.parent.Get(name)
	}
	return nil, false
}

// Evaluator evaluates an AST
type Evaluator struct {
	env   *Environment
	builtins map[string]BuiltinFunc
}

// BuiltinFunc is a built-in function
type BuiltinFunc func(...Value) (Value, error)

// NewEvaluator creates a new evaluator
func NewEvaluator() *Evaluator {
	e := &Evaluator{
		env:      NewEnvironment(),
		builtins: make(map[string]BuiltinFunc),
	}

	// Register built-in functions
	e.builtins["length"] = e.builtinLength
	e.builtins["keys"] = e.builtinKeys
	e.builtins["values"] = e.builtinValues
	e.builtins["type"] = e.builtinType
	e.builtins["merge"] = e.builtinMerge
	e.builtins["concat"] = e.builtinConcat
	e.builtins["contains"] = e.builtinContains
	e.builtins["upper"] = e.builtinUpper
	e.builtins["lower"] = e.builtinLower
	e.builtins["abs"] = e.builtinAbs
	e.builtins["max"] = e.builtinMax
	e.builtins["min"] = e.builtinMin
	e.builtins["sum"] = e.builtinSum
	e.builtins["join"] = e.builtinJoin
	e.builtins["split"] = e.builtinSplit

	return e
}

// Eval evaluates an expression
func (e *Evaluator) Eval(expr ast.Expr) (Value, error) {
	switch node := expr.(type) {
	case *ast.Literal:
		return e.evalLiteral(node)
	case *ast.Ident:
		return e.evalIdent(node)
	case *ast.BinaryOp:
		return e.evalBinaryOp(node)
	case *ast.UnaryOp:
		return e.evalUnaryOp(node)
	case *ast.Index:
		return e.evalIndex(node)
	case *ast.Attr:
		return e.evalAttr(node)
	case *ast.Call:
		return e.evalCall(node)
	case *ast.Block:
		return e.evalBlock(node)
	case *ast.List:
		return e.evalList(node)
	case *ast.Conditional:
		return e.evalConditional(node)
	default:
		return nil, fmt.Errorf("unknown expression type: %T", expr)
	}
}

// evalLiteral evaluates a literal
func (e *Evaluator) evalLiteral(lit *ast.Literal) (Value, error) {
	switch lit.Kind {
	case ast.KindString:
		return &String{Value: lit.Value.(string)}, nil
	case ast.KindNumber:
		return &Number{Value: lit.Value.(float64)}, nil
	case ast.KindBool:
		return &Bool{Value: lit.Value.(bool)}, nil
	case ast.KindNull:
		return &Null{}, nil
	default:
		return nil, fmt.Errorf("unknown literal kind: %v", lit.Kind)
	}
}

// evalIdent evaluates an identifier
func (e *Evaluator) evalIdent(ident *ast.Ident) (Value, error) {
	if val, ok := e.env.Get(ident.Name); ok {
		return val, nil
	}
	return nil, fmt.Errorf("undefined variable: %s", ident.Name)
}

// evalBinaryOp evaluates a binary operation
func (e *Evaluator) evalBinaryOp(binOp *ast.BinaryOp) (Value, error) {
	left, err := e.Eval(binOp.Left)
	if err != nil {
		return nil, err
	}

	right, err := e.Eval(binOp.Right)
	if err != nil {
		return nil, err
	}

	switch binOp.Op {
	case "+":
		return e.opAdd(left, right)
	case "-":
		return e.opSub(left, right)
	case "*":
		return e.opMul(left, right)
	case "/":
		return e.opDiv(left, right)
	case "%":
		return e.opMod(left, right)
	case "==":
		return &Bool{Value: IsEqual(left, right)}, nil
	case "!=":
		return &Bool{Value: !IsEqual(left, right)}, nil
	case "<":
		lt, err := IsLess(left, right)
		return &Bool{Value: lt}, err
	case "<=":
		lt, err := IsLess(left, right)
		if err != nil {
			return nil, err
		}
		eq := IsEqual(left, right)
		return &Bool{Value: lt || eq}, nil
	case ">":
		lt, err := IsLess(right, left)
		return &Bool{Value: lt}, err
	case ">=":
		lt, err := IsLess(right, left)
		if err != nil {
			return nil, err
		}
		eq := IsEqual(left, right)
		return &Bool{Value: lt || eq}, nil
	case "&&":
		return &Bool{Value: left.Truthy() && right.Truthy()}, nil
	case "||":
		return &Bool{Value: left.Truthy() || right.Truthy()}, nil
	default:
		return nil, fmt.Errorf("unknown binary operator: %s", binOp.Op)
	}
}

// evalUnaryOp evaluates a unary operation
func (e *Evaluator) evalUnaryOp(unaryOp *ast.UnaryOp) (Value, error) {
	expr, err := e.Eval(unaryOp.Expr)
	if err != nil {
		return nil, err
	}

	switch unaryOp.Op {
	case "!":
		return &Bool{Value: !expr.Truthy()}, nil
	case "-":
		num, err := ToNumber(expr)
		if err != nil {
			return nil, err
		}
		return &Number{Value: -num.Value}, nil
	case "+":
		return ToNumber(expr)
	default:
		return nil, fmt.Errorf("unknown unary operator: %s", unaryOp.Op)
	}
}

// evalIndex evaluates indexing
func (e *Evaluator) evalIndex(index *ast.Index) (Value, error) {
	expr, err := e.Eval(index.Expr)
	if err != nil {
		return nil, err
	}

	idx, err := e.Eval(index.Index)
	if err != nil {
		return nil, err
	}

	switch val := expr.(type) {
	case *List:
		num, err := ToNumber(idx)
		if err != nil {
			return nil, err
		}
		i := int64(num.Value)
		if i < 0 || i >= int64(len(val.Items)) {
			return &Null{}, nil
		}
		return val.Items[i], nil

	case *Map:
		key, err := ToString(idx)
		if err != nil {
			return nil, err
		}
		if v, ok := val.Pairs[key.Value]; ok {
			return v, nil
		}
		return &Null{}, nil

	case *String:
		num, err := ToNumber(idx)
		if err != nil {
			return nil, err
		}
		i := int64(num.Value)
		if i < 0 || i >= int64(len(val.Value)) {
			return &Null{}, nil
		}
		return &String{Value: string(val.Value[i])}, nil

	default:
		return nil, fmt.Errorf("cannot index %s", expr.Type())
	}
}

// evalAttr evaluates attribute access
func (e *Evaluator) evalAttr(attr *ast.Attr) (Value, error) {
	expr, err := e.Eval(attr.Expr)
	if err != nil {
		return nil, err
	}

	switch val := expr.(type) {
	case *Map:
		if v, ok := val.Pairs[attr.Attr]; ok {
			return v, nil
		}
		return &Null{}, nil
	default:
		return nil, fmt.Errorf("cannot access attribute on %s", expr.Type())
	}
}

// evalCall evaluates a function call
func (e *Evaluator) evalCall(call *ast.Call) (Value, error) {
	if builtin, ok := e.builtins[call.Name]; ok {
		args := make([]Value, len(call.Args))
		for i, arg := range call.Args {
			val, err := e.Eval(arg)
			if err != nil {
				return nil, err
			}
			args[i] = val
		}
		return builtin(args...)
	}

	return nil, fmt.Errorf("unknown function: %s", call.Name)
}

// evalBlock evaluates a block
func (e *Evaluator) evalBlock(block *ast.Block) (Value, error) {
	result := &Map{Pairs: make(map[string]Value)}
	for _, pair := range block.Pairs {
		val, err := e.Eval(pair.Value)
		if err != nil {
			return nil, err
		}
		result.Pairs[pair.Key] = val
	}
	return result, nil
}

// evalList evaluates a list
func (e *Evaluator) evalList(list *ast.List) (Value, error) {
	items := make([]Value, len(list.Items))
	for i, item := range list.Items {
		val, err := e.Eval(item)
		if err != nil {
			return nil, err
		}
		items[i] = val
	}
	return &List{Items: items}, nil
}

// evalConditional evaluates a conditional
func (e *Evaluator) evalConditional(cond *ast.Conditional) (Value, error) {
	condVal, err := e.Eval(cond.Cond)
	if err != nil {
		return nil, err
	}

	if condVal.Truthy() {
		return e.Eval(cond.True)
	}
	return e.Eval(cond.False)
}

// Arithmetic operations
func (e *Evaluator) opAdd(left, right Value) (Value, error) {
	switch l := left.(type) {
	case *Number:
		r, err := ToNumber(right)
		if err != nil {
			return nil, err
		}
		return &Number{Value: l.Value + r.Value}, nil

	case *String:
		r, err := ToString(right)
		if err != nil {
			return nil, err
		}
		return &String{Value: l.Value + r.Value}, nil

	case *List:
		switch r := right.(type) {
		case *List:
			result := make([]Value, len(l.Items)+len(r.Items))
			copy(result, l.Items)
			copy(result[len(l.Items):], r.Items)
			return &List{Items: result}, nil
		default:
			return nil, fmt.Errorf("cannot add %s to list", right.Type())
		}

	default:
		return nil, fmt.Errorf("cannot add %s and %s", left.Type(), right.Type())
	}
}

func (e *Evaluator) opSub(left, right Value) (Value, error) {
	l, err := ToNumber(left)
	if err != nil {
		return nil, err
	}
	r, err := ToNumber(right)
	if err != nil {
		return nil, err
	}
	return &Number{Value: l.Value - r.Value}, nil
}

func (e *Evaluator) opMul(left, right Value) (Value, error) {
	l, err := ToNumber(left)
	if err != nil {
		return nil, err
	}
	r, err := ToNumber(right)
	if err != nil {
		return nil, err
	}
	return &Number{Value: l.Value * r.Value}, nil
}

func (e *Evaluator) opDiv(left, right Value) (Value, error) {
	l, err := ToNumber(left)
	if err != nil {
		return nil, err
	}
	r, err := ToNumber(right)
	if err != nil {
		return nil, err
	}
	if r.Value == 0 {
		return nil, fmt.Errorf("division by zero")
	}
	return &Number{Value: l.Value / r.Value}, nil
}

func (e *Evaluator) opMod(left, right Value) (Value, error) {
	l, err := ToNumber(left)
	if err != nil {
		return nil, err
	}
	r, err := ToNumber(right)
	if err != nil {
		return nil, err
	}
	if r.Value == 0 {
		return nil, fmt.Errorf("modulo by zero")
	}
	return &Number{Value: math.Mod(l.Value, r.Value)}, nil
}

// Built-in functions
func (e *Evaluator) builtinLength(args ...Value) (Value, error) {
	if len(args) != 1 {
		return nil, fmt.Errorf("length expects 1 argument, got %d", len(args))
	}

	switch val := args[0].(type) {
	case *String:
		return &Number{Value: float64(len(val.Value))}, nil
	case *List:
		return &Number{Value: float64(len(val.Items))}, nil
	case *Map:
		return &Number{Value: float64(len(val.Pairs))}, nil
	default:
		return nil, fmt.Errorf("length not supported for %s", val.Type())
	}
}

func (e *Evaluator) builtinKeys(args ...Value) (Value, error) {
	if len(args) != 1 {
		return nil, fmt.Errorf("keys expects 1 argument, got %d", len(args))
	}

	m, ok := args[0].(*Map)
	if !ok {
		return nil, fmt.Errorf("keys expects a map, got %s", args[0].Type())
	}

	keys := make([]Value, len(m.Pairs))
	i := 0
	for k := range m.Pairs {
		keys[i] = &String{Value: k}
		i++
	}
	return &List{Items: keys}, nil
}

func (e *Evaluator) builtinValues(args ...Value) (Value, error) {
	if len(args) != 1 {
		return nil, fmt.Errorf("values expects 1 argument, got %d", len(args))
	}

	m, ok := args[0].(*Map)
	if !ok {
		return nil, fmt.Errorf("values expects a map, got %s", args[0].Type())
	}

	values := make([]Value, len(m.Pairs))
	i := 0
	for _, v := range m.Pairs {
		values[i] = v
		i++
	}
	return &List{Items: values}, nil
}

func (e *Evaluator) builtinType(args ...Value) (Value, error) {
	if len(args) != 1 {
		return nil, fmt.Errorf("type expects 1 argument, got %d", len(args))
	}
	return &String{Value: args[0].Type()}, nil
}

func (e *Evaluator) builtinMerge(args ...Value) (Value, error) {
	result := &Map{Pairs: make(map[string]Value)}

	for _, arg := range args {
		m, ok := arg.(*Map)
		if !ok {
			return nil, fmt.Errorf("merge expects maps, got %s", arg.Type())
		}
		for k, v := range m.Pairs {
			result.Pairs[k] = v
		}
	}

	return result, nil
}

func (e *Evaluator) builtinConcat(args ...Value) (Value, error) {
	result := &List{Items: []Value{}}

	for _, arg := range args {
		switch val := arg.(type) {
		case *List:
			result.Items = append(result.Items, val.Items...)
		case *String:
			result.Items = append(result.Items, &String{Value: val.Value})
		default:
			return nil, fmt.Errorf("concat expects lists or strings, got %s", arg.Type())
		}
	}

	return result, nil
}

func (e *Evaluator) builtinContains(args ...Value) (Value, error) {
	if len(args) != 2 {
		return nil, fmt.Errorf("contains expects 2 arguments, got %d", len(args))
	}

	switch container := args[0].(type) {
	case *String:
		needle, err := ToString(args[1])
		if err != nil {
			return nil, err
		}
		found := false
		for _, ch := range container.Value {
			if string(ch) == needle.Value {
				found = true
				break
			}
		}
		return &Bool{Value: found}, nil

	case *List:
		for _, item := range container.Items {
			if IsEqual(item, args[1]) {
				return &Bool{Value: true}, nil
			}
		}
		return &Bool{Value: false}, nil

	default:
		return nil, fmt.Errorf("contains not supported for %s", container.Type())
	}
}

func (e *Evaluator) builtinUpper(args ...Value) (Value, error) {
	if len(args) != 1 {
		return nil, fmt.Errorf("upper expects 1 argument, got %d", len(args))
	}

	s, err := ToString(args[0])
	if err != nil {
		return nil, err
	}

	return &String{Value: strings.ToUpper(s.Value)}, nil
}

func (e *Evaluator) builtinLower(args ...Value) (Value, error) {
	if len(args) != 1 {
		return nil, fmt.Errorf("lower expects 1 argument, got %d", len(args))
	}

	s, err := ToString(args[0])
	if err != nil {
		return nil, err
	}

	return &String{Value: strings.ToLower(s.Value)}, nil
}

func (e *Evaluator) builtinAbs(args ...Value) (Value, error) {
	if len(args) != 1 {
		return nil, fmt.Errorf("abs expects 1 argument, got %d", len(args))
	}

	n, err := ToNumber(args[0])
	if err != nil {
		return nil, err
	}

	return &Number{Value: math.Abs(n.Value)}, nil
}

func (e *Evaluator) builtinMax(args ...Value) (Value, error) {
	if len(args) == 0 {
		return nil, fmt.Errorf("max expects at least 1 argument")
	}

	max := args[0]
	for i := 1; i < len(args); i++ {
		lt, err := IsLess(max, args[i])
		if err != nil {
			return nil, err
		}
		if lt {
			max = args[i]
		}
	}

	return max, nil
}

func (e *Evaluator) builtinMin(args ...Value) (Value, error) {
	if len(args) == 0 {
		return nil, fmt.Errorf("min expects at least 1 argument")
	}

	min := args[0]
	for i := 1; i < len(args); i++ {
		lt, err := IsLess(args[i], min)
		if err != nil {
			return nil, err
		}
		if lt {
			min = args[i]
		}
	}

	return min, nil
}

func (e *Evaluator) builtinSum(args ...Value) (Value, error) {
	if len(args) == 0 {
		return &Number{Value: 0}, nil
	}

	sum := 0.0
	for _, arg := range args {
		switch val := arg.(type) {
		case *List:
			for _, item := range val.Items {
				n, err := ToNumber(item)
				if err != nil {
					return nil, err
				}
				sum += n.Value
			}
		default:
			n, err := ToNumber(arg)
			if err != nil {
				return nil, err
			}
			sum += n.Value
		}
	}

	return &Number{Value: sum}, nil
}

func (e *Evaluator) builtinJoin(args ...Value) (Value, error) {
	if len(args) != 2 {
		return nil, fmt.Errorf("join expects 2 arguments, got %d", len(args))
	}

	sep, err := ToString(args[1])
	if err != nil {
		return nil, err
	}

	switch val := args[0].(type) {
	case *List:
		var parts []string
		for _, item := range val.Items {
			s, err := ToString(item)
			if err != nil {
				return nil, err
			}
			parts = append(parts, s.Value)
		}
		return &String{Value: strings.Join(parts, sep.Value)}, nil

	default:
		return nil, fmt.Errorf("join expects a list, got %s", val.Type())
	}
}

func (e *Evaluator) builtinSplit(args ...Value) (Value, error) {
	if len(args) != 2 {
		return nil, fmt.Errorf("split expects 2 arguments, got %d", len(args))
	}

	str, err := ToString(args[0])
	if err != nil {
		return nil, err
	}

	sep, err := ToString(args[1])
	if err != nil {
		return nil, err
	}

	parts := strings.Split(str.Value, sep.Value)
	items := make([]Value, len(parts))
	for i, part := range parts {
		items[i] = &String{Value: part}
	}

	return &List{Items: items}, nil
}

package interpreter

import (
	"fmt"
	"math"
	"strings"

	"github.com/kimjindol2025/freelang-iac/internal/iac/ast"
)

// Environment holds variable bindings
type Environment struct {
	vars   map[string]Value
	parent *Environment
}

// NewEnvironment creates a new environment
func NewEnvironment() *Environment {
	return &Environment{
		vars:   make(map[string]Value),
		parent: nil,
	}
}

// NewChild creates a child environment
func (e *Environment) NewChild() *Environment {
	return &Environment{
		vars:   make(map[string]Value),
		parent: e,
	}
}

// Set sets a variable in the current environment
func (e *Environment) Set(name string, value Value) {
	e.vars[name] = value
}

// Get retrieves a variable, checking parent environments
func (e *Environment) Get(name string) (Value, bool) {
	if val, ok := e.vars[name]; ok {
		return val, true
	}
	if e.parent != nil {
		return e.parent.Get(name)
	}
	return nil, false
}

// Evaluator evaluates an AST
type Evaluator struct {
	Env      *Environment
	builtins map[string]BuiltinFunc
}

// BuiltinFunc is a built-in function
type BuiltinFunc func(...Value) (Value, error)

// NewEvaluator creates a new evaluator
func NewEvaluator() *Evaluator {
	e := &Evaluator{
		env:      NewEnvironment(),
		builtins: make(map[string]BuiltinFunc),
	}

	// Register built-in functions
	e.builtins["length"] = e.builtinLength
	e.builtins["keys"] = e.builtinKeys
	e.builtins["values"] = e.builtinValues
	e.builtins["type"] = e.builtinType
	e.builtins["merge"] = e.builtinMerge
	e.builtins["concat"] = e.builtinConcat
	e.builtins["contains"] = e.builtinContains
	e.builtins["upper"] = e.builtinUpper
	e.builtins["lower"] = e.builtinLower
	e.builtins["abs"] = e.builtinAbs
	e.builtins["max"] = e.builtinMax
	e.builtins["min"] = e.builtinMin
	e.builtins["sum"] = e.builtinSum
	e.builtins["join"] = e.builtinJoin
	e.builtins["split"] = e.builtinSplit

	return e
}

// Eval evaluates an expression
func (e *Evaluator) Eval(expr ast.Expr) (Value, error) {
	switch node := expr.(type) {
	case *ast.Literal:
		return e.evalLiteral(node)
	case *ast.Ident:
		return e.evalIdent(node)
	case *ast.BinaryOp:
		return e.evalBinaryOp(node)
	case *ast.UnaryOp:
		return e.evalUnaryOp(node)
	case *ast.Index:
		return e.evalIndex(node)
	case *ast.Attr:
		return e.evalAttr(node)
	case *ast.Call:
		return e.evalCall(node)
	case *ast.Block:
		return e.evalBlock(node)
	case *ast.List:
		return e.evalList(node)
	case *ast.Conditional:
		return e.evalConditional(node)
	default:
		return nil, fmt.Errorf("unknown expression type: %T", expr)
	}
}

// evalLiteral evaluates a literal
func (e *Evaluator) evalLiteral(lit *ast.Literal) (Value, error) {
	switch lit.Kind {
	case ast.KindString:
		return &String{Value: lit.Value.(string)}, nil
	case ast.KindNumber:
		return &Number{Value: lit.Value.(float64)}, nil
	case ast.KindBool:
		return &Bool{Value: lit.Value.(bool)}, nil
	case ast.KindNull:
		return &Null{}, nil
	default:
		return nil, fmt.Errorf("unknown literal kind: %v", lit.Kind)
	}
}

// evalIdent evaluates an identifier
func (e *Evaluator) evalIdent(ident *ast.Ident) (Value, error) {
	if val, ok := e.env.Get(ident.Name); ok {
		return val, nil
	}
	return nil, fmt.Errorf("undefined variable: %s", ident.Name)
}

// evalBinaryOp evaluates a binary operation
func (e *Evaluator) evalBinaryOp(binOp *ast.BinaryOp) (Value, error) {
	left, err := e.Eval(binOp.Left)
	if err != nil {
		return nil, err
	}

	right, err := e.Eval(binOp.Right)
	if err != nil {
		return nil, err
	}

	switch binOp.Op {
	case "+":
		return e.opAdd(left, right)
	case "-":
		return e.opSub(left, right)
	case "*":
		return e.opMul(left, right)
	case "/":
		return e.opDiv(left, right)
	case "%":
		return e.opMod(left, right)
	case "==":
		return &Bool{Value: IsEqual(left, right)}, nil
	case "!=":
		return &Bool{Value: !IsEqual(left, right)}, nil
	case "<":
		lt, err := IsLess(left, right)
		return &Bool{Value: lt}, err
	case "<=":
		lt, err := IsLess(left, right)
		if err != nil {
			return nil, err
		}
		eq := IsEqual(left, right)
		return &Bool{Value: lt || eq}, nil
	case ">":
		lt, err := IsLess(right, left)
		return &Bool{Value: lt}, err
	case ">=":
		lt, err := IsLess(right, left)
		if err != nil {
			return nil, err
		}
		eq := IsEqual(left, right)
		return &Bool{Value: lt || eq}, nil
	case "&&":
		return &Bool{Value: left.Truthy() && right.Truthy()}, nil
	case "||":
		return &Bool{Value: left.Truthy() || right.Truthy()}, nil
	default:
		return nil, fmt.Errorf("unknown binary operator: %s", binOp.Op)
	}
}

// evalUnaryOp evaluates a unary operation
func (e *Evaluator) evalUnaryOp(unaryOp *ast.UnaryOp) (Value, error) {
	expr, err := e.Eval(unaryOp.Expr)
	if err != nil {
		return nil, err
	}

	switch unaryOp.Op {
	case "!":
		return &Bool{Value: !expr.Truthy()}, nil
	case "-":
		num, err := ToNumber(expr)
		if err != nil {
			return nil, err
		}
		return &Number{Value: -num.Value}, nil
	case "+":
		return ToNumber(expr)
	default:
		return nil, fmt.Errorf("unknown unary operator: %s", unaryOp.Op)
	}
}

// evalIndex evaluates indexing
func (e *Evaluator) evalIndex(index *ast.Index) (Value, error) {
	expr, err := e.Eval(index.Expr)
	if err != nil {
		return nil, err
	}

	idx, err := e.Eval(index.Index)
	if err != nil {
		return nil, err
	}

	switch val := expr.(type) {
	case *List:
		num, err := ToNumber(idx)
		if err != nil {
			return nil, err
		}
		i := int64(num.Value)
		if i < 0 || i >= int64(len(val.Items)) {
			return &Null{}, nil
		}
		return val.Items[i], nil

	case *Map:
		key, err := ToString(idx)
		if err != nil {
			return nil, err
		}
		if v, ok := val.Pairs[key.Value]; ok {
			return v, nil
		}
		return &Null{}, nil

	case *String:
		num, err := ToNumber(idx)
		if err != nil {
			return nil, err
		}
		i := int64(num.Value)
		if i < 0 || i >= int64(len(val.Value)) {
			return &Null{}, nil
		}
		return &String{Value: string(val.Value[i])}, nil

	default:
		return nil, fmt.Errorf("cannot index %s", expr.Type())
	}
}

// evalAttr evaluates attribute access
func (e *Evaluator) evalAttr(attr *ast.Attr) (Value, error) {
	expr, err := e.Eval(attr.Expr)
	if err != nil {
		return nil, err
	}

	switch val := expr.(type) {
	case *Map:
		if v, ok := val.Pairs[attr.Attr]; ok {
			return v, nil
		}
		return &Null{}, nil
	default:
		return nil, fmt.Errorf("cannot access attribute on %s", expr.Type())
	}
}

// evalCall evaluates a function call
func (e *Evaluator) evalCall(call *ast.Call) (Value, error) {
	if builtin, ok := e.builtins[call.Name]; ok {
		args := make([]Value, len(call.Args))
		for i, arg := range call.Args {
			val, err := e.Eval(arg)
			if err != nil {
				return nil, err
			}
			args[i] = val
		}
		return builtin(args...)
	}

	return nil, fmt.Errorf("unknown function: %s", call.Name)
}

// evalBlock evaluates a block
func (e *Evaluator) evalBlock(block *ast.Block) (Value, error) {
	result := &Map{Pairs: make(map[string]Value)}
	for _, pair := range block.Pairs {
		val, err := e.Eval(pair.Value)
		if err != nil {
			return nil, err
		}
		result.Pairs[pair.Key] = val
	}
	return result, nil
}

// evalList evaluates a list
func (e *Evaluator) evalList(list *ast.List) (Value, error) {
	items := make([]Value, len(list.Items))
	for i, item := range list.Items {
		val, err := e.Eval(item)
		if err != nil {
			return nil, err
		}
		items[i] = val
	}
	return &List{Items: items}, nil
}

// evalConditional evaluates a conditional
func (e *Evaluator) evalConditional(cond *ast.Conditional) (Value, error) {
	condVal, err := e.Eval(cond.Cond)
	if err != nil {
		return nil, err
	}

	if condVal.Truthy() {
		return e.Eval(cond.True)
	}
	return e.Eval(cond.False)
}

// Arithmetic operations
func (e *Evaluator) opAdd(left, right Value) (Value, error) {
	switch l := left.(type) {
	case *Number:
		r, err := ToNumber(right)
		if err != nil {
			return nil, err
		}
		return &Number{Value: l.Value + r.Value}, nil

	case *String:
		r, err := ToString(right)
		if err != nil {
			return nil, err
		}
		return &String{Value: l.Value + r.Value}, nil

	case *List:
		switch r := right.(type) {
		case *List:
			result := make([]Value, len(l.Items)+len(r.Items))
			copy(result, l.Items)
			copy(result[len(l.Items):], r.Items)
			return &List{Items: result}, nil
		default:
			return nil, fmt.Errorf("cannot add %s to list", right.Type())
		}

	default:
		return nil, fmt.Errorf("cannot add %s and %s", left.Type(), right.Type())
	}
}

func (e *Evaluator) opSub(left, right Value) (Value, error) {
	l, err := ToNumber(left)
	if err != nil {
		return nil, err
	}
	r, err := ToNumber(right)
	if err != nil {
		return nil, err
	}
	return &Number{Value: l.Value - r.Value}, nil
}

func (e *Evaluator) opMul(left, right Value) (Value, error) {
	l, err := ToNumber(left)
	if err != nil {
		return nil, err
	}
	r, err := ToNumber(right)
	if err != nil {
		return nil, err
	}
	return &Number{Value: l.Value * r.Value}, nil
}

func (e *Evaluator) opDiv(left, right Value) (Value, error) {
	l, err := ToNumber(left)
	if err != nil {
		return nil, err
	}
	r, err := ToNumber(right)
	if err != nil {
		return nil, err
	}
	if r.Value == 0 {
		return nil, fmt.Errorf("division by zero")
	}
	return &Number{Value: l.Value / r.Value}, nil
}

func (e *Evaluator) opMod(left, right Value) (Value, error) {
	l, err := ToNumber(left)
	if err != nil {
		return nil, err
	}
	r, err := ToNumber(right)
	if err != nil {
		return nil, err
	}
	if r.Value == 0 {
		return nil, fmt.Errorf("modulo by zero")
	}
	return &Number{Value: math.Mod(l.Value, r.Value)}, nil
}

// Built-in functions
func (e *Evaluator) builtinLength(args ...Value) (Value, error) {
	if len(args) != 1 {
		return nil, fmt.Errorf("length expects 1 argument, got %d", len(args))
	}

	switch val := args[0].(type) {
	case *String:
		return &Number{Value: float64(len(val.Value))}, nil
	case *List:
		return &Number{Value: float64(len(val.Items))}, nil
	case *Map:
		return &Number{Value: float64(len(val.Pairs))}, nil
	default:
		return nil, fmt.Errorf("length not supported for %s", val.Type())
	}
}

func (e *Evaluator) builtinKeys(args ...Value) (Value, error) {
	if len(args) != 1 {
		return nil, fmt.Errorf("keys expects 1 argument, got %d", len(args))
	}

	m, ok := args[0].(*Map)
	if !ok {
		return nil, fmt.Errorf("keys expects a map, got %s", args[0].Type())
	}

	keys := make([]Value, len(m.Pairs))
	i := 0
	for k := range m.Pairs {
		keys[i] = &String{Value: k}
		i++
	}
	return &List{Items: keys}, nil
}

func (e *Evaluator) builtinValues(args ...Value) (Value, error) {
	if len(args) != 1 {
		return nil, fmt.Errorf("values expects 1 argument, got %d", len(args))
	}

	m, ok := args[0].(*Map)
	if !ok {
		return nil, fmt.Errorf("values expects a map, got %s", args[0].Type())
	}

	values := make([]Value, len(m.Pairs))
	i := 0
	for _, v := range m.Pairs {
		values[i] = v
		i++
	}
	return &List{Items: values}, nil
}

func (e *Evaluator) builtinType(args ...Value) (Value, error) {
	if len(args) != 1 {
		return nil, fmt.Errorf("type expects 1 argument, got %d", len(args))
	}
	return &String{Value: args[0].Type()}, nil
}

func (e *Evaluator) builtinMerge(args ...Value) (Value, error) {
	result := &Map{Pairs: make(map[string]Value)}

	for _, arg := range args {
		m, ok := arg.(*Map)
		if !ok {
			return nil, fmt.Errorf("merge expects maps, got %s", arg.Type())
		}
		for k, v := range m.Pairs {
			result.Pairs[k] = v
		}
	}

	return result, nil
}

func (e *Evaluator) builtinConcat(args ...Value) (Value, error) {
	result := &List{Items: []Value{}}

	for _, arg := range args {
		switch val := arg.(type) {
		case *List:
			result.Items = append(result.Items, val.Items...)
		case *String:
			result.Items = append(result.Items, &String{Value: val.Value})
		default:
			return nil, fmt.Errorf("concat expects lists or strings, got %s", arg.Type())
		}
	}

	return result, nil
}

func (e *Evaluator) builtinContains(args ...Value) (Value, error) {
	if len(args) != 2 {
		return nil, fmt.Errorf("contains expects 2 arguments, got %d", len(args))
	}

	switch container := args[0].(type) {
	case *String:
		needle, err := ToString(args[1])
		if err != nil {
			return nil, err
		}
		found := false
		for _, ch := range container.Value {
			if string(ch) == needle.Value {
				found = true
				break
			}
		}
		return &Bool{Value: found}, nil

	case *List:
		for _, item := range container.Items {
			if IsEqual(item, args[1]) {
				return &Bool{Value: true}, nil
			}
		}
		return &Bool{Value: false}, nil

	default:
		return nil, fmt.Errorf("contains not supported for %s", container.Type())
	}
}

func (e *Evaluator) builtinUpper(args ...Value) (Value, error) {
	if len(args) != 1 {
		return nil, fmt.Errorf("upper expects 1 argument, got %d", len(args))
	}

	s, err := ToString(args[0])
	if err != nil {
		return nil, err
	}

	return &String{Value: strings.ToUpper(s.Value)}, nil
}

func (e *Evaluator) builtinLower(args ...Value) (Value, error) {
	if len(args) != 1 {
		return nil, fmt.Errorf("lower expects 1 argument, got %d", len(args))
	}

	s, err := ToString(args[0])
	if err != nil {
		return nil, err
	}

	return &String{Value: strings.ToLower(s.Value)}, nil
}

func (e *Evaluator) builtinAbs(args ...Value) (Value, error) {
	if len(args) != 1 {
		return nil, fmt.Errorf("abs expects 1 argument, got %d", len(args))
	}

	n, err := ToNumber(args[0])
	if err != nil {
		return nil, err
	}

	return &Number{Value: math.Abs(n.Value)}, nil
}

func (e *Evaluator) builtinMax(args ...Value) (Value, error) {
	if len(args) == 0 {
		return nil, fmt.Errorf("max expects at least 1 argument")
	}

	max := args[0]
	for i := 1; i < len(args); i++ {
		lt, err := IsLess(max, args[i])
		if err != nil {
			return nil, err
		}
		if lt {
			max = args[i]
		}
	}

	return max, nil
}

func (e *Evaluator) builtinMin(args ...Value) (Value, error) {
	if len(args) == 0 {
		return nil, fmt.Errorf("min expects at least 1 argument")
	}

	min := args[0]
	for i := 1; i < len(args); i++ {
		lt, err := IsLess(args[i], min)
		if err != nil {
			return nil, err
		}
		if lt {
			min = args[i]
		}
	}

	return min, nil
}

func (e *Evaluator) builtinSum(args ...Value) (Value, error) {
	if len(args) == 0 {
		return &Number{Value: 0}, nil
	}

	sum := 0.0
	for _, arg := range args {
		switch val := arg.(type) {
		case *List:
			for _, item := range val.Items {
				n, err := ToNumber(item)
				if err != nil {
					return nil, err
				}
				sum += n.Value
			}
		default:
			n, err := ToNumber(arg)
			if err != nil {
				return nil, err
			}
			sum += n.Value
		}
	}

	return &Number{Value: sum}, nil
}

func (e *Evaluator) builtinJoin(args ...Value) (Value, error) {
	if len(args) != 2 {
		return nil, fmt.Errorf("join expects 2 arguments, got %d", len(args))
	}

	sep, err := ToString(args[1])
	if err != nil {
		return nil, err
	}

	switch val := args[0].(type) {
	case *List:
		var parts []string
		for _, item := range val.Items {
			s, err := ToString(item)
			if err != nil {
				return nil, err
			}
			parts = append(parts, s.Value)
		}
		return &String{Value: strings.Join(parts, sep.Value)}, nil

	default:
		return nil, fmt.Errorf("join expects a list, got %s", val.Type())
	}
}

func (e *Evaluator) builtinSplit(args ...Value) (Value, error) {
	if len(args) != 2 {
		return nil, fmt.Errorf("split expects 2 arguments, got %d", len(args))
	}

	str, err := ToString(args[0])
	if err != nil {
		return nil, err
	}

	sep, err := ToString(args[1])
	if err != nil {
		return nil, err
	}

	parts := strings.Split(str.Value, sep.Value)
	items := make([]Value, len(parts))
	for i, part := range parts {
		items[i] = &String{Value: part}
	}

	return &List{Items: items}, nil
}

package engine

import (
	"fmt"

	"github.com/kimjindol2025/freelang-iac/internal/iac/ast"
	"github.com/kimjindol2025/freelang-iac/internal/iac/interpreter"
	"github.com/kimjindol2025/freelang-iac/internal/iac/lexer"
	"github.com/kimjindol2025/freelang-iac/internal/iac/parser"
)

// Engine orchestrates lexing, parsing, and evaluation
type Engine struct {
	source    string
	tokens    []lexer.Token
	program   *ast.Program
	evaluator *interpreter.Evaluator
	errors    []string
}

// NewEngine creates a new engine
func NewEngine(source string) *Engine {
	return &Engine{
		source:    source,
		errors:    []string{},
		evaluator: interpreter.NewEvaluator(),
	}
}

// Lex tokenizes the source code
func (e *Engine) Lex() error {
	lex := lexer.NewLexer(e.source)
	e.tokens = lex.TokenizeAll()

	// Check for lexer errors
	for _, tok := range e.tokens {
		if tok.Type == lexer.TokenError {
			e.errors = append(e.errors, fmt.Sprintf("Lexer error at %d:%d: %s", tok.Line, tok.Col, tok.Value))
		}
	}

	if len(e.errors) > 0 {
		return fmt.Errorf("lexing failed")
	}

	return nil
}

// Parse builds the AST
func (e *Engine) Parse() error {
	if len(e.tokens) == 0 {
		return fmt.Errorf("no tokens to parse")
	}

	p := parser.NewParser(e.tokens)
	e.program = p.Parse()

	if len(p.Errors()) > 0 {
		e.errors = append(e.errors, p.Errors()...)
		return fmt.Errorf("parsing failed")
	}

	return nil
}

// Evaluate runs the program
func (e *Engine) Evaluate() error {
	if e.program == nil {
		return fmt.Errorf("no program to evaluate")
	}

	for _, stmt := range e.program.Statements {
		if err := e.evaluateStatement(stmt); err != nil {
			e.errors = append(e.errors, err.Error())
		}
	}

	if len(e.errors) > 0 {
		return fmt.Errorf("evaluation failed")
	}

	return nil
}

// evaluateStatement evaluates a single statement
func (e *Engine) evaluateStatement(stmt ast.Stmt) error {
	switch node := stmt.(type) {
	case *ast.Resource:
		return e.evaluateResource(node)
	case *ast.Data:
		return e.evaluateData(node)
	case *ast.Variable:
		return e.evaluateVariable(node)
	case *ast.Output:
		return e.evaluateOutput(node)
	case *ast.Local:
		return e.evaluateLocal(node)
	case *ast.Module:
		return e.evaluateModule(node)
	default:
		return fmt.Errorf("unknown statement type: %T", stmt)
	}
}

// evaluateResource evaluates a resource block
func (e *Engine) evaluateResource(resource *ast.Resource) error {
	if resource.Block == nil {
		return fmt.Errorf("resource %q %q has no block", resource.Type, resource.Name)
	}

	// Store resource in evaluator environment
	key := fmt.Sprintf("%s_%s", resource.Type, resource.Name)
	val, err := e.evaluator.Eval(resource.Block)
	if err != nil {
		return fmt.Errorf("failed to evaluate resource %q: %w", key, err)
	}

	e.evaluator.env.Set(key, val)
	return nil
}

// evaluateData evaluates a data block
func (e *Engine) evaluateData(data *ast.Data) error {
	if data.Block == nil {
		return fmt.Errorf("data %q %q has no block", data.Type, data.Name)
	}

	// Store data in evaluator environment
	key := fmt.Sprintf("data_%s_%s", data.Type, data.Name)
	val, err := e.evaluator.Eval(data.Block)
	if err != nil {
		return fmt.Errorf("failed to evaluate data %q: %w", key, err)
	}

	e.evaluator.env.Set(key, val)
	return nil
}

// evaluateVariable evaluates a variable block
func (e *Engine) evaluateVariable(variable *ast.Variable) error {
	if variable.Block == nil {
		return fmt.Errorf("variable %q has no block", variable.Name)
	}

	// Store variable in evaluator environment
	val, err := e.evaluator.Eval(variable.Block)
	if err != nil {
		return fmt.Errorf("failed to evaluate variable %q: %w", variable.Name, err)
	}

	e.evaluator.env.Set(fmt.Sprintf("var_%s", variable.Name), val)
	return nil
}

// evaluateOutput evaluates an output block
func (e *Engine) evaluateOutput(output *ast.Output) error {
	if output.Block == nil {
		return fmt.Errorf("output %q has no block", output.Name)
	}

	// Store output in evaluator environment
	val, err := e.evaluator.Eval(output.Block)
	if err != nil {
		return fmt.Errorf("failed to evaluate output %q: %w", output.Name, err)
	}

	e.evaluator.env.Set(fmt.Sprintf("output_%s", output.Name), val)
	return nil
}

// evaluateLocal evaluates a local block
func (e *Engine) evaluateLocal(local *ast.Local) error {
	if local.Block == nil {
		return fmt.Errorf("local block has no pairs")
	}

	// Evaluate local values
	val, err := e.evaluator.Eval(local.Block)
	if err != nil {
		return fmt.Errorf("failed to evaluate local: %w", err)
	}

	// Store locals in evaluator environment
	if m, ok := val.(*interpreter.Map); ok {
		for k, v := range m.Pairs {
			e.evaluator.env.Set(fmt.Sprintf("local_%s", k), v)
		}
	}

	return nil
}

// evaluateModule evaluates a module block
func (e *Engine) evaluateModule(module *ast.Module) error {
	if module.Block == nil {
		return fmt.Errorf("module %q has no block", module.Name)
	}

	// Store module in evaluator environment
	val, err := e.evaluator.Eval(module.Block)
	if err != nil {
		return fmt.Errorf("failed to evaluate module %q: %w", module.Name, err)
	}

	e.evaluator.env.Set(fmt.Sprintf("module_%s", module.Name), val)
	return nil
}

// Run executes all phases: lex, parse, evaluate
func (e *Engine) Run() error {
	if err := e.Lex(); err != nil {
		return err
	}

	if err := e.Parse(); err != nil {
		return err
	}

	if err := e.Evaluate(); err != nil {
		return err
	}

	return nil
}

// GetVariable retrieves a variable value
func (e *Engine) GetVariable(name string) (interpreter.Value, bool) {
	return e.evaluator.env.Get(name)
}

// GetAllVariables returns all variables in the environment
func (e *Engine) GetAllVariables() map[string]interpreter.Value {
	vars := make(map[string]interpreter.Value)

	// This is a simplified version - a full implementation would walk the environment
	// For now, we'll just return an empty map
	return vars
}

// Errors returns all accumulated errors
func (e *Engine) Errors() []string {
	return e.errors
}

// HasErrors checks if there are any errors
func (e *Engine) HasErrors() bool {
	return len(e.errors) > 0
}

